Translate the following GNU C++14 code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include<cstdio>
#include<cstring>
#include<vector>
#include<algorithm>
#include<utility>
using namespace std;
using i64 = long long;
i64 C[62][62], valA[32][32], valB[32][32];
int rows, cols, halfLen;
char pattern[110];
i64 total, globalMin;
vector<pair<i64,i64>> fwd[32][2], bwd[32][2];
i64 pathsCount[32][32];
i64 answer;

void record(int x, int y, i64 sum, i64 cnt1, i64 cnt2, bool rev) {
    if (x + y == halfLen) {
        fwd[x][rev].emplace_back(sum, cnt1);
        if (cnt2) bwd[x][rev].emplace_back(sum, cnt2);
        return;
    }
    record(x+1, y, sum + (!rev ? valA[x+1][y] : 0), cnt1, (pattern[x+y] != 'B' ? cnt2 : 0), rev);
    record(x, y+1, sum + (rev ? valB[x][y+1] : 0), cnt1, (pattern[x+y] != 'A' ? cnt2 : 0), rev);
}

void explore(int x, int y, i64 acc, bool rev) {
    if (x + y == halfLen) {
        if (fwd[x][rev].empty()) return;
        auto it = lower_bound(fwd[x][rev].begin(), fwd[x][rev].end(), make_pair((total+1)/2 - acc, 0LL));
        if (it != fwd[x][rev].end() && it->second > 0) {
            i64 diff = abs((it->first + acc) * 2 - total);
            if (diff < globalMin) globalMin = diff;
        }
        if (it != fwd[x][rev].begin()) {
            --it;
            if (it->second > 0) {
                i64 diff = abs((it->first + acc) * 2 - total);
                if (diff < globalMin) globalMin = diff;
            }
        }
        return;
    }
    if (x > 0) explore(x-1, y, acc + (!rev ? valA[x][y] : 0), rev);
    if (y > 0) explore(x, y-1, acc + (rev ? valB[x][y] : 0), rev);
}

void countMatches(int x, int y, i64 acc, bool rev) {
    if (x + y == halfLen) {
        auto it = lower_bound(bwd[x][rev].begin(), bwd[x][rev].end(), make_pair((total+1)/2 - acc, 0LL));
        if (it != bwd[x][rev].end() && it->second > 0) {
            i64 diff = abs((it->first + acc) * 2 - total);
            if (diff == globalMin) answer += it->second;
        }
        if (it != bwd[x][rev].begin()) {
            --it;
            if (it->second > 0) {
                i64 diff = abs((it->first + acc) * 2 - total);
                if (diff == globalMin) answer += it->second;
            }
        }
        return;
    }
    if (x > 0 && pattern[x+y-1] != 'B') countMatches(x-1, y, acc + (!rev ? valA[x][y] : 0), rev);
    if (y > 0 && pattern[x+y-1] != 'A') countMatches(x, y-1, acc + (rev ? valB[x][y] : 0), rev);
}

void dedup(vector<pair<i64,i64>>& v) {
    if (v.empty()) return;
    sort(v.begin(), v.end());
    int k = 0;
    i64 accumulate = 0;
    for (int i = 0; i < (int)v.size(); ++i) {
        accumulate += v[i].second;
        if (i == (int)v.size()-1 || v[i].first != v[i+1].first) {
            v[k++] = {v[i].first, accumulate};
            accumulate = 0;
        }
    }
    v.resize(k);
}

int main() {
    scanf("%d%d", &rows, &cols);
    scanf("%s", pattern);
    for (int i = 0; i <= 60; ++i) {
        C[i][0] = 1;
        for (int j = 1; j <= i; ++j)
            C[i][j] = C[i-1][j-1] + C[i-1][j];
    }
    halfLen = rows + cols;
    total = C[halfLen*2][rows*2];
    for (int i = 0; i <= halfLen; ++i)
        for (int j = 0; j <= halfLen; ++j) {
            if (i) valA[i][j] = C[i-1][rows-1] * (C[halfLen*2-i][rows] - C[j][rows]);
            if (j) valB[i][j] = C[j-1][rows-1] * (C[halfLen*2-j][rows] - C[i][rows]);
        }
    pathsCount[0][0] = 1;
    for (int i = 0; i <= halfLen; ++i)
        for (int j = 0; j <= halfLen; ++j) {
            if (i < halfLen && pattern[i+j] != 'B') pathsCount[i+1][j] += pathsCount[i][j];
            if (j < halfLen && pattern[i+j] != 'A') pathsCount[i][j+1] += pathsCount[i][j];
        }
    for (int i = rows; i <= halfLen; ++i) {
        if (pattern[i+rows-1] != 'B') record(rows, i, valA[rows][i], C[i+rows-1][rows-1], pathsCount[rows-1][i], false);
        if (pattern[i+rows-1] != 'A') record(i, rows, valB[i][rows], C[i+rows-1][rows-1], pathsCount[i][rows-1], true);
    }
    for (int i = rows; i <= halfLen; ++i)
        for (int d = 0; d < 2; ++d) {
            dedup(fwd[i][d]);
            dedup(bwd[i][d]);
        }
    globalMin = total + 1;
    explore(halfLen, halfLen, 0, false);
    explore(halfLen, halfLen, 0, true);
    countMatches(halfLen, halfLen, 0, false);
    countMatches(halfLen, halfLen, 0, true);
    printf("%lld\n", answer);
}
